exercise.schema:
CREATE TABLE regions (code text PRIMARY KEY);
CREATE TABLE servers (id int PRIMARY KEY, region_code text NOT NULL REFERENCES regions(code));
CREATE TABLE matches (id int PRIMARY KEY, server_id int NOT NULL REFERENCES servers(id), status text NOT NULL CHECK (status IN ('finished', 'abandoned', 'in_progress')));

